; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================


p_title_show_c:		; call show (normal)
			ld (p_title_show_rs), sp
			ld hl, ovl_blk_intro	; page PAGES.001
			ld de, p_title_show_pg
			ld ix, p_title_show_in
			jp ntc_ovl_enter
p_title_show_in:
			ld sp, p_title_show
			jp ntc_xn
p_title_show_r:		; end of show
			ld sp, (ntc_csp)		; the caller's page back
			ld hl, (p_title_show_pg)
			call mem_sel
			ld sp, (p_title_show_rs)
			jp ntc_xn
p_level1_play_c:		; call play (normal)
			ld hl, 0
			ld (var_level1_play_i), hl
			ld (p_level1_play_rs), sp
			ld hl, ovl_blk_stage1	; page PAGES.002
			ld de, p_level1_play_pg
			ld ix, p_level1_play_in
			jp ntc_ovl_enter
p_level1_play_in:
			ld sp, p_level1_play
			jp ntc_xn
p_level1_play_r:		; end of play
			ld sp, (ntc_csp)		; the caller's page back
			ld hl, (p_level1_play_pg)
			call mem_sel
			ld sp, (p_level1_play_rs)
			jp ntc_xn
p_level2_play_c:		; call play (normal)
			ld (p_level2_play_rs), sp
			ld hl, ovl_blk_stage2	; page PAGES.003
			ld de, p_level2_play_pg
			ld ix, p_level2_play_in
			jp ntc_ovl_enter
p_level2_play_in:
			ld sp, p_level2_play
			jp ntc_xn
p_level2_play_r:		; end of play
			ld sp, (ntc_csp)		; the caller's page back
			ld hl, (p_level2_play_pg)
			call mem_sel
			ld sp, (p_level2_play_rs)
			jp ntc_xn
p_maths_square_c:		; call square (normal)
			pop hl			; n
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_maths_square_n), de
			ld hl, 0
			ld (var_maths_square_square), hl
			ld (p_maths_square_rs), sp
			ld a, (ntc_ovl_lc)	; called from its own page?
			or a
			jr z, p_maths_square_far
			xor a
			ld (ntc_ovl_lc), a
			dec a
			ld (p_maths_square_pg), a	; #FF..: no page back on return
			ld (p_maths_square_pg+1), a
			jr p_maths_square_in
p_maths_square_far:
			ld hl, p_maths_square_ct	; its copies (Stage1, Stage2)
			ld de, p_maths_square_pg
			ld ix, p_maths_square_in
			jp ntc_ovl_enterc
p_maths_square_in:
			ld sp, (ntc_ovl_body)
			jp ntc_xn
p_maths_square_r:		; end of square
			ld hl, (p_maths_square_pg)
			ld a, h
			and l
			inc a
			jr z, p_maths_square_rb	; a call from its own page: nothing to switch back
			ld sp, (ntc_csp)		; the caller's page back
			ld hl, (p_maths_square_pg)
			call mem_sel
p_maths_square_rb:
			ld sp, (p_maths_square_rs)
			jp ntc_xn
p_stars_add_c:		; call add (normal)
			ld (p_stars_add_rs), sp
			ld a, (ntc_ovl_lc)	; called from its own page?
			or a
			jr z, p_stars_add_far
			xor a
			ld (ntc_ovl_lc), a
			dec a
			ld (p_stars_add_pg), a	; #FF..: no page back on return
			ld (p_stars_add_pg+1), a
			jr p_stars_add_in
p_stars_add_far:
			ld hl, p_stars_add_ct	; its copies (Stage1, Stage2)
			ld de, p_stars_add_pg
			ld ix, p_stars_add_in
			jp ntc_ovl_enterc
p_stars_add_in:
			ld sp, (ntc_ovl_body)
			jp ntc_xn
p_stars_add_r:		; end of add
			ld hl, (p_stars_add_pg)
			ld a, h
			and l
			inc a
			jr z, p_stars_add_rb	; a call from its own page: nothing to switch back
			ld sp, (ntc_csp)		; the caller's page back
			ld hl, (p_stars_add_pg)
			call mem_sel
p_stars_add_rb:
			ld sp, (p_stars_add_rs)
			jp ntc_xn
p_stars_count_c:		; call count (normal)
			ld hl, 0
			ld (var_stars_count_count), hl
			ld (p_stars_count_rs), sp
			ld a, (ntc_ovl_lc)	; called from its own page?
			or a
			jr z, p_stars_count_far
			xor a
			ld (ntc_ovl_lc), a
			dec a
			ld (p_stars_count_pg), a	; #FF..: no page back on return
			ld (p_stars_count_pg+1), a
			jr p_stars_count_in
p_stars_count_far:
			ld hl, p_stars_count_ct	; its copies (Stage1, Stage2)
			ld de, p_stars_count_pg
			ld ix, p_stars_count_in
			jp ntc_ovl_enterc
p_stars_count_in:
			ld sp, (ntc_ovl_body)
			jp ntc_xn
p_stars_count_r:		; end of count
			ld hl, (p_stars_count_pg)
			ld a, h
			and l
			inc a
			jr z, p_stars_count_rb	; a call from its own page: nothing to switch back
			ld sp, (ntc_csp)		; the caller's page back
			ld hl, (p_stars_count_pg)
			call mem_sel
p_stars_count_rb:
			ld sp, (p_stars_count_rs)
			jp ntc_xn
p_credits_show_c:		; call show (normal)
			ld (p_credits_show_rs), sp
			ld hl, ovl_blk_ending	; page PAGES.004
			ld de, p_credits_show_pg
			ld ix, p_credits_show_in
			jp ntc_ovl_enter
p_credits_show_in:
			ld sp, p_credits_show
			jp ntc_xn
p_credits_show_r:		; end of show
			ld sp, (ntc_csp)		; the caller's page back
			ld hl, (p_credits_show_pg)
			call mem_sel
			ld sp, (p_credits_show_rs)
			jp ntc_xn
p_score_add_c:		; call add (normal)
			pop hl			; n
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_score_add_n), de
			ld (p_score_add_rs), sp
			ld sp, p_score_add
			jp ntc_xn
p_score_add_r:		; end of add
			ld sp, (p_score_add_rs)
			jp ntc_xn
p_score_total_c:		; call total (normal)
			ld hl, 0
			ld (var_score_total_total), hl
			ld (p_score_total_rs), sp
			ld sp, p_score_total
			jp ntc_xn
p_score_total_r:		; end of total
			ld sp, (p_score_total_rs)
			jp ntc_xn

